// Exercise Bun string conversion before serving: its <=32-byte fast path
// would conceal an unsupported simdutf backend. Expected bytes come from UTF-8
// and UTF-16 reference encodings, not a round trip through the same backend.
const cases = [{"id":"ascii-0","pattern":"A","repeat":0,"base64":"","unit":[65],"unit16le":[65,0]},{"id":"ascii-1","pattern":"A","repeat":1,"base64":"QQ==","unit":[65],"unit16le":[65,0]},{"id":"ascii-15","pattern":"A","repeat":15,"base64":"QUFBQUFBQUFBQUFBQUFB","unit":[65],"unit16le":[65,0]},{"id":"ascii-16","pattern":"A","repeat":16,"base64":"QUFBQUFBQUFBQUFBQUFBQQ==","unit":[65],"unit16le":[65,0]},{"id":"ascii-31","pattern":"A","repeat":31,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQQ==","unit":[65],"unit16le":[65,0]},{"id":"ascii-32","pattern":"A","repeat":32,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUE=","unit":[65],"unit16le":[65,0]},{"id":"ascii-33","pattern":"A","repeat":33,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFB","unit":[65],"unit16le":[65,0]},{"id":"ascii-63","pattern":"A","repeat":63,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFB","unit":[65],"unit16le":[65,0]},{"id":"ascii-64","pattern":"A","repeat":64,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQQ==","unit":[65],"unit16le":[65,0]},{"id":"ascii-65","pattern":"A","repeat":65,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUE=","unit":[65],"unit16le":[65,0]},{"id":"ascii-127","pattern":"A","repeat":127,"base64":"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQQ==","unit":[65],"unit16le":[65,0]},{"id":"ascii-256","pattern":"A","repeat":256,"base64":"","unit":[65],"unit16le":[65,0]},{"id":"ascii-4096","pattern":"A","repeat":4096,"base64":"","unit":[65],"unit16le":[65,0]},{"id":"latin1","pattern":"éÿñ","repeat":80,"base64":"","unit":[195,169,195,191,195,177],"unit16le":[233,0,255,0,241,0]},{"id":"cjk","pattern":"你好，运行环境。","repeat":70,"base64":"","unit":[228,189,160,229,165,189,239,188,140,232,191,144,232,161,140,231,142,175,229,162,131,227,128,130],"unit16le":[96,79,125,89,12,255,208,143,76,136,175,115,131,88,2,48]},{"id":"astral","pattern":"🚀𐐷𝄞","repeat":80,"base64":"","unit":[240,159,154,128,240,144,144,183,240,157,132,158],"unit16le":[61,216,128,222,1,216,55,220,52,216,30,221]},{"id":"mixed","pattern":"Aé中文🚀Z","repeat":90,"base64":"","unit":[65,195,169,228,184,173,230,150,135,240,159,154,128,90],"unit16le":[65,0,233,0,45,78,135,101,61,216,128,222,90,0]}];
let assertions = 0;
const check = (value, message) => { if (!value) throw new Error(message); assertions++; };
for (const c of cases) {
  c.text = c.pattern.repeat(c.repeat);
  c.utf8 = Array.from({length: c.unit.length * c.repeat}, (_, i) => c.unit[i % c.unit.length]);
  const encoded = new TextEncoder().encode(c.text);
  check(encoded.length === c.utf8.length && encoded.every((v, i) => v === c.utf8[i]), c.id + ': TextEncoder');
  check(new TextDecoder().decode(Uint8Array.from(c.utf8)) === c.text, c.id + ': TextDecoder');
  check(Buffer.from(c.text).toString('base64') === c.base64, c.id + ': base64 encode');
  check(Buffer.from(c.base64, 'base64').equals(Buffer.from(c.utf8)), c.id + ': base64 decode');
  check(await new Response(c.text).text() === c.text, c.id + ': Response');
  const utf16le = Uint8Array.from({length: c.unit16le.length * c.repeat}, (_, i) => c.unit16le[i % c.unit16le.length]);
  check(Buffer.from(c.text, 'utf16le').equals(Buffer.from(utf16le)), c.id + ': UTF16 encode');
  check(Buffer.from(utf16le).toString('utf16le') === c.text, c.id + ': UTF16 decode');
  check(new TextDecoder('utf-16le').decode(utf16le) === c.text, c.id + ': TextDecoder UTF16');

}
const malformed = new TextEncoder().encode('A\ud800B');
check(JSON.stringify(Array.from(malformed)) === '[65,239,191,189,66]', 'unpaired surrogate replacement');
const binary = Uint8Array.from({length: 512}, (_, i) => i & 255);
check(Buffer.from(Buffer.from(binary).toString('base64'), 'base64').equals(Buffer.from(binary)), 'all byte values');
console.log(JSON.stringify({schema_version: 1, cases: cases.length, assertions, status: 'passed', description: 'Long ASCII and Unicode runtime conversion checks passed'}));

let count = 0;
Bun.serve({
  hostname: "0.0.0.0",
  port: Number(Bun.argv[2] || 8080),
  async fetch(request) {
    const current = ++count;
    const chunks = [];
    let length = 0;
    const headers = { "Content-Type": "application/json", "Connection": "close" };
    if (request.body) {
      const reader = request.body.getReader();
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        length += value.length;
        if (length > 65536) {
          await reader.cancel();
          return new Response('{"error":"Body too large"}', { status: 413, headers });
        }
        chunks.push(value);
      }
    }
    const bytes = new Uint8Array(length);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.length;
    }
    const pathStart = request.url.indexOf("/", request.url.indexOf("://") + 3);
    const path = pathStart < 0 ? "/" : request.url.slice(pathStart);
    const payload = JSON.stringify({
      family: "bun", method: request.method, path,
      body: new TextDecoder().decode(bytes), count: current,
    });
    headers["Content-Length"] = String(new TextEncoder().encode(payload).length);
    return new Response(payload, { headers });
  },
});
